import{_ as s,c as t,o as n,j as e,a as i}from"./chunks/framework.Dnh4IO1K.js";const _=JSON.parse('{"title":"乾下艮上 大畜：","description":"京氏易传 - 乾下艮上 大畜：","frontmatter":{"title":"乾下艮上 大畜：","description":"京氏易传 - 乾下艮上 大畜："},"headers":[],"relativePath":"zh/classics/jingshi/028.md","filePath":"zh/classics/jingshi/028.md"}'),r={name:"zh/classics/jingshi/028.md"};function l(c,a,o,d,p,h){return n(),t("div",null,[...a[0]||(a[0]=[e("h1",{id:"乾下艮上-大畜",tabindex:"-1"},[i("乾下艮上 大畜： "),e("a",{class:"header-anchor",href:"#乾下艮上-大畜","aria-label":"Permalink to “乾下艮上 大畜：”"},"​")],-1),e("p",null,"阳长阴消，积气凝盛，外止内健，二阴犹盛，成于畜义。《易》云：“既雨既处。”（虎易注：此句是《小畜》卦上九爻词，作者引用有误。）畜消时行，阳未可进。取于下卦，全其健道，君子以时顺其吉凶。与乾为飞伏。【甲寅木，丙午火。】",-1),e("p",null,"建始壬辰至丁酉，【清明至秋分。】积算起丁酉至丙申，周而复始。【金土入卦分吉凶起算。】",-1),e("p",null,"五星从位起太白，【太白金星入卦推吉凶。】毕宿从位降甲寅。【毕宿入大畜九二甲寅上。】九二大夫应世，应六五为至尊，阴阳相应，以柔居尊。（缺）为畜之主。分气候二十八。【极阴阳之象，定吉凶之兆。】",-1),e("p",null,"山下有乾，金土相资。阳进阴止，积雨润下，畜道光也。乾象内进，君道行也。吉凶升降，阴阳得位，二气相应，阳上薄阴，阴道凝结。上于阳长，为雨反下，九居高位，极于畜道。反阳为阴，入于兑象。六三应上九，上有阳九，反应六三，成于损道。次降损卦。【乾入兑九三之变六二。】",-1)])])}const f=s(r,[["render",l]]);export{_ as __pageData,f as default};
